/* state layer（黒 8%/16% の重畳）を各コンポーネントで共通利用するための custom utility。
   variant（[&:hover:not([data-disabled])] 等）はコンポーネント側で付与する。 */
@utility state-layer-8 {
  background-image: linear-gradient(
    var(--color-state-layers-dark-opacity-8),
    var(--color-state-layers-dark-opacity-8)
  );
}

@utility state-layer-16 {
  background-image: linear-gradient(
    var(--color-state-layers-dark-opacity-16),
    var(--color-state-layers-dark-opacity-16)
  );
}

